      try{await coverViewTransition();if(!this._closed)await this.$router.push(path);}
      finally{if(!this._closed)this.departing=false;setTimeout(revealViewTransition,420);}
    },
    async enterView(view,resume=true){
      if(this.departing||!view?.id)return;
      this._visitSequence=(this._visitSequence||0)+1;
      this.departing=true;this.entryError='';this.selected=view;this.hoveredCatalogueId='';
      this.panelOpen=false;this.directoryExpanded=false;this.readingExpanded=false;this.area='collection';
      this.stationVisible=true;this.walkingAway=false;this.travelling=true;
      this._keyboard?.clear();this._scene?.setExhibition(view);this.rememberHall();
      updateMuseumSession({mode:'museum',resumeOnViews:false});
      try {
        // One uninterrupted walk passes through the entrance. Loading runs
        // alongside it, with the pavilion visible until the threshold.
        let prepared=false;
        await Promise.all([
          this._scene?.go('entry').then(()=>{if(!this._closed&&this.departing&&!prepared)this.entryWaiting=true;}),
          prepareMuseumVisit(view.id).then(()=>{prepared=true;}),
        ]);
        if(this._closed)return;
        this.entryWaiting=false;
        await coverViewTransition();
        if(this._closed)return;
        updateMuseumSession({lastView:{id:view.id,title:view.title,position:resume?museumReturnPosition(view.id):null}});
        await this.$router.push(`/view/${view.id}`);
      } catch {
        this.departing=false;this.travelling=false;this.entryWaiting=false;
        this.entryError='This exhibition could not open. Please try again.';
        revealViewTransition();
      }
    },
    dateTime(value){const date=new Date(typeof value==='string'&&/^\d+$/.test(value)?Number(value):value);return Number.isNaN(date.getTime())?'':date.toISOString();},
    dateLabel(value){return value?new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',year:'numeric'}).format(new Date(value)):'';},
  },
